mapper.select:


    and category = #{category}
    and match_type = #{matchType}
    and pattern ilike concat('%', #{pattern}, '%')
    and status = #{status}

        and (platforms = '[]'::jsonb or platforms @> jsonb_build_array(cast(#{params.platform} as text)))


order by category, match_type, rule_id

mapper.update:
update abr_compliance_rule
set category = #{category}, match_type = #{matchType}, pattern = #{pattern}, action = #{action},
    platforms = cast(#{platforms} as jsonb), status = #{status}, update_by = #{updateBy}, update_time = now(), remark = #{remark}
where rule_id = #{ruleId}
